#include "../../../src/cascadia/inc/SftpLocal.h"
#include <fstream>
#include <iostream>
using namespace Microsoft::Terminal::Backslash::Transfers::Sftp;
int wmain(int argc,wchar_t**argv){try{if(argc!=2)throw std::runtime_error("Owned absent root required");const std::filesystem::path root=argv[1];if(std::filesystem::exists(root))throw std::runtime_error("Collision");std::filesystem::create_directory(root);const auto final=root/L"marker.txt";{LocalTemporary temporary(final.wstring());temporary.Write("owned-marker");temporary.Publish(false);Handle read(CreateFileW(final.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));const auto error=GetLastError();if(read.value!=INVALID_HANDLE_VALUE||error!=ERROR_SHARING_VIOLATION)throw std::runtime_error("Expected sharing violation not observed");std::cout<<"Published file while LocalTemporary retained: ERROR_SHARING_VIOLATION=32\n";}std::ifstream file(final,std::ios::binary);const std::string bytes{std::istreambuf_iterator<char>(file),{}};if(bytes!="owned-marker")throw std::runtime_error("Published bytes mismatch after handle release");std::cout<<"PASS: exact marker readable after publication owner releases; no network.\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
